mapper.select:
SELECT

FROM recommendations
WHERE user_id = #{userId}
AND deleted = 0
ORDER BY created_at DESC
LIMIT #{offset}, #{limit}

mapper.insert:
INSERT INTO recommendations (
user_id, video_id, content, scene_type, scene_description,
created_at, updated_at, deleted
) VALUES (
#{userId}, #{videoId}, #{content}, #{sceneType}, #{sceneDescription},
#{createdAt}, #{updatedAt}, #{deleted}
)

mapper.update:
UPDATE recommendations
content = #{content}, scene_type = #{sceneType}, scene_description = #{sceneDescription}, updated_at = #{updatedAt}
WHERE id = #{id} AND deleted = 0
